import{_ as e,o as s,c as o,ag as t}from"./chunks/framework.B3amng90.js";const i="/abu-aigc-guide/screenshots/canvas-list.webp",r="/abu-aigc-guide/screenshots/canvas-nodes.webp",n="/abu-aigc-guide/examples/canvas-connection.webp",l="/abu-aigc-guide/examples/canvas-materials.webp",b=JSON.parse('{"title":"用无限画布组合素材","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/canvas.md","filePath":"workflows/canvas.md"}'),c={name:"workflows/canvas.md"};function p(g,a,d,h,m,u){return s(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="用无限画布组合素材" tabindex="-1">用无限画布组合素材 <a class="header-anchor" href="#用无限画布组合素材" aria-label="Permalink to &quot;用无限画布组合素材&quot;">​</a></h1><p>画布适合把创作拆成多个可回看的步骤。文字、图片、视频和音频可以放在不同节点中，再通过连线传递给后续生成。</p><h2 id="新建或打开画布" tabindex="-1">新建或打开画布 <a class="header-anchor" href="#新建或打开画布" aria-label="Permalink to &quot;新建或打开画布&quot;">​</a></h2><p>在侧栏的 <strong>近期画布</strong> 点 <strong>全部</strong>，进入 <strong>我的作品</strong> 页面。选择 <strong>个人画布</strong>，点击 <strong>新建画布</strong>，或打开已有画布继续编辑。</p><p><a href="/abu-aigc-guide/screenshots/canvas-list.webp"><img src="'+i+'" alt="我的作品页的个人画布标签和新建画布卡片" loading="lazy"></a></p><p><em>在「个人画布」里找到新建入口。点击截图可查看大图。</em></p><h2 id="从素材开始生成" tabindex="-1">从素材开始生成 <a class="header-anchor" href="#从素材开始生成" aria-label="Permalink to &quot;从素材开始生成&quot;">​</a></h2><p><a href="/abu-aigc-guide/screenshots/canvas-nodes.webp"><img src="'+r+'" alt="画布左侧加号展开的添加节点菜单，右侧是一个图片节点" loading="lazy"></a></p><p><em>打开画布左侧的加号，可以添加生成节点、文本或已有素材。</em></p><ol><li>点击左侧的 <strong>＋（添加节点）</strong>，添加文本或素材节点，写下提示词，或从资产库选择已保存的图片、视频和音频。</li><li>添加需要的生成节点，并将参考节点连接到它。连线表示哪些内容会作为生成输入。</li><li>选择当前可用的模型，填写提示词并检查生成参数。</li><li>提交任务后，在节点中查看进度和结果。可以调整描述或参数后重新生成，也可以把结果接到下一个节点。</li><li>对满意的结果，可继续用于后续创作或保存到片库。</li></ol><h2 id="完整案例-参考图连接到视频节点" tabindex="-1">完整案例：参考图连接到视频节点 <a class="header-anchor" href="#完整案例-参考图连接到视频节点" aria-label="Permalink to &quot;完整案例：参考图连接到视频节点&quot;">​</a></h2><p>生产环境中的这张画布使用生成历史里的图片节点作为参考，再连接到视频生成节点。可以按下面的顺序复现：</p><ol><li>打开 <strong>资产库</strong>，从 <strong>生成历史 → 图片</strong> 选择一张已有结果，例如未来城市车站图。</li><li>添加一个 <strong>文本</strong> 节点，写下场景和镜头提示词：<code>未来城市玻璃穹顶车站，镜头沿中央通道缓慢前推，冷白建筑光与蓝色行星反光，电影级空间感，9:16 竖屏</code>。</li><li>添加 <strong>视频生成</strong> 节点，在节点中填写运动描述，并点击 <strong>引用画布里的素材</strong>，选择城市图。系统会自动建立连线，并切换到支持参考素材的生成方式。</li><li>在视频节点里选择 <strong>muse-video</strong>，检查参数后再决定是否开始生成。</li></ol><p><a href="/abu-aigc-guide/examples/canvas-connection.webp"><img src="'+n+'" alt="生产画布中已有图片、提示词和视频节点的引用连线" loading="lazy"></a></p><p><em>截图展示真实连线、参考素材和视频节点；没有提交新的生成任务。点击截图可查看大图。</em></p><p><a href="/abu-aigc-guide/examples/canvas-materials.webp"><img src="'+l+'" alt="生产画布中的生成历史图片节点和提示词节点" loading="lazy"></a></p><p><em>先把生成历史里的作品引入画布，再补充文字提示词。</em></p><h2 id="编辑画布" tabindex="-1">编辑画布 <a class="header-anchor" href="#编辑画布" aria-label="Permalink to &quot;编辑画布&quot;">​</a></h2><p>拖动节点调整布局；拖动节点连接点建立或修改连线。选中节点后，可查看或编辑提示词、素材和生成设置。节点保留生成结果，便于比较迭代版本。图片和视频节点还可使用各自提供的编辑操作。</p><p>画布会自动保存。若同时在多个标签页编辑同一张画布，请留意冲突提示，确认保留正确版本后再继续。</p><h2 id="让结果更可控" tabindex="-1">让结果更可控 <a class="header-anchor" href="#让结果更可控" aria-label="Permalink to &quot;让结果更可控&quot;">​</a></h2><ul><li>一轮只改少数提示词或参数，方便比较差异。</li><li>将常用角色、场景和参考图整理为独立节点，重复使用时不必重新准备。</li><li>生成前确认所选模型支持对应素材类型、画幅和时长。</li><li>使用画布 Agent 修改内容后，检查节点与连线是否符合预期；不合适时使用撤销。</li></ul>',22)])])}const f=e(c,[["render",p]]);export{b as __pageData,f as default};
